3	 * General Utility class that solve generic issues that appear frequently
4	 *
5	 * @version 1.0
6	 */
7	public final class Utils
8	{
9	
10	    private static Random rand = Randomizer.getRandom();
11	    
12	    /**
13	     * Throws an exception as a utility class cannot be instantiated.
14	     */
15	    private Utils()
16	    {
17	        throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
18	    }
19	    
20	    /**
21	     * Returns a random value from the set of possible values in an enumerator.
22	     * 
23	     * @param enumerator The enumaretor of a given class from which the values are taken.
24	     * @return T a random value from the set of possible values in an enumerator.
25	     */
26	    public static <T extends Enum<?>> T getRandomEnumValue(Class<T> enumerator){
27	        int x = rand.nextInt(enumerator.getEnumConstants().length);
28	        return enumerator.getEnumConstants()[x];
29	    }
30	    
31	    /**
32	     * Formats a String by adding padding to the right.
33	     * 
34	     * @param data String to which the padding is added.
35	     * @param n number of padding spaces.
36	     * @return a formatted String.
37	     */
38	    public static String padRight(String data, int n)
39	    {
40	       return String.format("%-" + n +  "s", data).replace(" ", "0");
41	    }
42	    
43	    /**
44	     * Formats a String by adding padding to the left.
45	     * 
46	     * @param data String to which the padding is added.
47	     * @param n number of padding spaces.
48	     * @return a formatted String.
49	     */
50	    public static String padLeft(String data, int n)
51	    {
